INSERT INTO `quest_template` (`ID`, `QuestType`, `QuestLevel`, `MinLevel`, `QuestSortID`, `QuestInfoID`, `SuggestedGroupNum`, `RewardXPDifficulty`, `RewardMoney`, `Flags`, `AllowableRaces`, `LogTitle`, `LogDescription`, `QuestDescription`, `AreaDescription`, `QuestCompletionLog`, `RequiredItemId1`, `RequiredItemCount1`, `RewardItem1`, `RewardAmount1`, `VerifiedBuild`) VALUES
(921001, 2, 60, 58, 51, 0, 0, 0, 0, 0, 0, 'Shadows Over Blackrock', 'Speak with Kaelastrasz at Thorium Point.', 'Above us, in the spire of Blackrock, Nefarian breathes a fire that is not fire: Shadowflame, the dark flame of Deathwing''s line. It burns flesh and soul alike, and no mortal armor turns it.$B$BOnce, champions wore cloaks of Onyxia''s own scales against it. Her scales are not enough on their own. But a ward woven from the scales of all five flights, bound with the scale of the Broodmother herself... that, $N, would hold.$B$BWill you gather them?', '', 'Return to Kaelastrasz at Thorium Point in the Searing Gorge.', 0, 0, 0, 0, 0),
(921002, 2, 60, 58, 51, 0, 0, 0, 30000, 0, 0, 'Scales of the Black Brood', 'Bring 8 Black Dragonflight Scales to Kaelastrasz at Thorium Point.', 'The black brood is the heart of the ward: only a black scale knows Shadowflame for what it is. The Burning Steppes crawl with Nefarian''s dragonkin. Take their scales, $N. Eight should be enough.', '', 'Return to Kaelastrasz at Thorium Point in the Searing Gorge.', 912101, 8, 0, 0, 0),
(921003, 2, 60, 58, 51, 0, 0, 0, 40000, 0, 0, 'Vexathrax', 'Bring the Pristine Black Dragonflight Scale from Vexathrax to Kaelastrasz at Thorium Point.', 'Common scales hold the weave, but the ward needs a heartscale for each flight: one taken from a dragon of true age and strength. In the Burning Steppes a drake named Vexathrax hunts for its master. Bring me its pristine scale.', '', 'Return to Kaelastrasz at Thorium Point in the Searing Gorge.', 912106, 1, 0, 0, 0),
(921004, 2, 60, 58, 51, 0, 0, 0, 30000, 0, 0, 'Scales of the Red Brood', 'Bring 8 Red Dragonflight Scales to Kaelastrasz at Thorium Point.', 'It grieves me to ask it. My own flight''s dragonkin still haunt Grim Batol, in the Wetlands, maddened by what the Dragonmaw did to them there. They will not listen to reason any longer. Bring me eight of their scales, $N, and be quick about it.', '', 'Return to Kaelastrasz at Thorium Point in the Searing Gorge.', 912102, 8, 0, 0, 0),
(921005, 2, 60, 58, 51, 0, 0, 0, 40000, 0, 0, 'Pyraxis', 'Bring the Pristine Red Dragonflight Scale from Pyraxis to Kaelastrasz at Thorium Point.', 'A drake of my flight called Pyraxis rules Grim Batol''s broken gates now, and the madness is deepest in him. End it, $N, and bring me his heartscale. He would have wanted it to protect someone.', '', 'Return to Kaelastrasz at Thorium Point in the Searing Gorge.', 912107, 1, 0, 0, 0),
(921006, 2, 60, 58, 51, 0, 0, 0, 30000, 0, 0, 'Scales of the Blue Brood', 'Bring 8 Blue Dragonflight Scales to Kaelastrasz at Thorium Point.', 'Malygos''s children guard their magic jealously in the caves of Mazthoril, in Winterspring. A blue scale will hold the weave together where fire would tear it apart. Bring me eight.', '', 'Return to Kaelastrasz at Thorium Point in the Searing Gorge.', 912103, 8, 0, 0, 0),
(921007, 2, 60, 58, 51, 0, 0, 0, 40000, 0, 0, 'Azurathys', 'Bring the Pristine Blue Dragonflight Scale from Azurathys to Kaelastrasz at Thorium Point.', 'The blue heartscale must come from Azurathys, who guards the blue dragonkin''s camp in Azshara. Azurathys is old and proud, and will not give it willingly.', '', 'Return to Kaelastrasz at Thorium Point in the Searing Gorge.', 912108, 1, 0, 0, 0),
(921008, 2, 60, 58, 51, 0, 0, 0, 30000, 0, 0, 'Scales of the Dreaming', 'Bring 8 Green Dragonflight Scales to Kaelastrasz at Thorium Point.', 'Something has gone wrong in the Emerald Dream. Ysera''s dragonkin now guard the great trees at Seradane in the Hinterlands, Bough Shadow in Ashenvale and the Dream Bough in Feralas, and they attack anyone who comes near. Their scales will keep the ward from burning. Bring me eight, from any of the three.', '', 'Return to Kaelastrasz at Thorium Point in the Searing Gorge.', 912104, 8, 0, 0, 0),
(921009, 2, 60, 58, 51, 0, 0, 0, 40000, 0, 0, 'Scales of the Timeless', 'Bring the Bronze Dragonflight Scale from Chronalis to Kaelastrasz at Thorium Point.', 'The bronze flight gives nothing freely, least of all to me. At the Caverns of Time in Tanaris, Chronalis tests all who come near. Pass his test the hard way, $N: one bronze scale will anchor the ward in time, so it cannot fade.', '', 'Return to Kaelastrasz at Thorium Point in the Searing Gorge.', 912105, 1, 0, 0, 0),
(921010, 2, 60, 58, 51, 0, 0, 0, 0, 0, 0, 'The Scales Assembled', 'Speak with Kaelastrasz at Thorium Point.', 'Black, red, blue, green and bronze. All five flights, laid out together for the first time in an age. I can weave them now, $N, but the weave will not hold Shadowflame... not yet.', '', 'Return to Kaelastrasz at Thorium Point in the Searing Gorge.', 0, 0, 0, 0, 0),
(921011, 2, 60, 58, 51, 0, 0, 0, 100000, 0, 0, 'Scale of the Broodmother', 'Bring the Scale of Onyxia to Kaelastrasz at Thorium Point.', 'Shadowflame is Deathwing''s fire, and only his own blood can turn it. Onyxia, his daughter, lairs in Dustwallow Marsh. Slay her and take a scale from her hide: with it I can bind the five flights'' scales into one ward.', '', 'Return to Kaelastrasz at Thorium Point in the Searing Gorge.', 15410, 1, 912109, 1, 0),
(921012, 2, 60, 58, 51, 0, 0, 0, 0, 0, 0, 'The Shadowflame Ward', 'Give the Unfinished Shadowflame Ward to Kaelastrasz at Thorium Point.', 'Everything is ready, $N. Give me the weave and I will bind it with the fire of my flight. When it is done, no Shadowflame will touch you.', '', 'Return to Kaelastrasz at Thorium Point in the Searing Gorge.', 912109, 1, 912100, 1, 0);
