INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES
(921001, 0, 0, 0, 0, 0, 0, 0, 0, 'Then we begin. Five flights, five scales. Go where you will; I will be here.', 0),
(921002, 0, 0, 0, 0, 0, 0, 0, 0, 'Dark and still warm. Good.', 0),
(921003, 0, 0, 0, 0, 0, 0, 0, 0, 'A pristine heartscale. Vexathrax will not be missed.', 0),
(921004, 0, 0, 0, 0, 0, 0, 0, 0, 'Red as the life they guarded. Thank you, $N.', 0),
(921005, 0, 0, 0, 0, 0, 0, 0, 0, 'Rest now, Pyraxis.', 0),
(921006, 0, 0, 0, 0, 0, 0, 0, 0, 'Cold to the touch, and humming with arcane power. Perfect.', 0),
(921007, 0, 0, 0, 0, 0, 0, 0, 0, 'It still glows. Azshara will be quieter now.', 0),
(921008, 0, 0, 0, 0, 0, 0, 0, 0, 'They smell of rain and nightmares. These will do.', 0),
(921009, 0, 0, 0, 0, 0, 0, 0, 0, 'It is warm and ticks like a heartbeat. Nozdormu will understand. I hope.', 0),
(921010, 0, 0, 0, 0, 0, 0, 0, 0, 'One scale remains, and it is the one that matters most.', 0),
(921011, 0, 0, 0, 0, 0, 0, 0, 0, 'Her scale... At last. Here, take the weave while I prepare the binding. Do not let it out of your sight.', 0),
(921012, 0, 0, 0, 0, 0, 0, 0, 0, 'It is done. Wear it into Blackwing Lair, and let Nefarian''s fire break against the scales of every flight he has wronged.', 0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES
(921002, 0, 0, 'Have you brought the black scales?', 0),
(921003, 0, 0, 'Is Vexathrax dead?', 0),
(921004, 0, 0, 'Did you find my kin in Grim Batol?', 0),
(921005, 0, 0, 'Is it done?', 0),
(921006, 0, 0, 'Have you been to Mazthoril?', 0),
(921007, 0, 0, 'Azurathys?', 0),
(921008, 0, 0, 'Did the Dream let you go?', 0),
(921009, 0, 0, 'Did Chronalis yield?', 0),
(921011, 0, 0, 'Is the Broodmother dead?', 0),
(921012, 0, 0, 'The weave, $N.', 0);
